const input = $input.first().json.body || $input.first().json;

// Asset to upload
const assetId = input.asset_id;
if (!assetId) throw new Error('Must provide asset_id');

// Optional: teaser package for marketing copy
const teaserPackageId = input.teaser_package_id || null;

// Platforms to upload to
const platforms = input.platforms || ['gumroad'];
const validPlatforms = ['gumroad', 'etsy', 'amazon_kdp', 'shopify', 'payhip', 'lemonsqueezy', 'kofi', 'teachable', 'thinkific'];
const selectedPlatforms = platforms.filter(p => validPlatforms.includes(p));

// Pricing configuration
const pricing = {
  base_price: input.pricing?.base_price || 9.99,
  currency: input.pricing?.currency || 'USD',

  // Platform-specific pricing adjustments
  platform_adjustments: input.pricing?.platform_adjustments || {},

  // Promotional pricing
  launch_discount: input.pricing?.launch_discount || null, // e.g., { percent: 20, days: 7 }

  // Pay what you want
  pwyw_enabled: input.pricing?.pwyw_enabled || false,
  pwyw_minimum: input.pricing?.pwyw_minimum || 0,
  pwyw_suggested: input.pricing?.pwyw_suggested || null,

  // Tiers (for courses/bundles)
  tiers: input.pricing?.tiers || null
};

// Product configuration
const product = {
  type: input.product?.type || 'ebook', // ebook, course, template, printable, software

  // Categorization
  category: input.product?.category || 'Business',
  subcategory: input.product?.subcategory || 'Productivity',
  tags: input.product?.tags || [],

  // Visibility
  visibility: input.product?.visibility || 'public', // public, unlisted, private

  // Scheduling
  publish_mode: input.product?.publish_mode || 'immediate', // immediate, scheduled, draft
  scheduled_date: input.product?.scheduled_date || null,

  // Adult content flag
  is_adult: input.product?.is_adult || false,

  // Refund policy
  refund_policy: input.product?.refund_policy || '30_days' // no_refunds, 7_days, 30_days
};

// Content delivery options
const delivery = {
  // Which file formats to include
  include_formats: input.delivery?.include_formats || ['pdf', 'epub'],

  // Bonus content
  include_bonuses: input.delivery?.include_bonuses || true,
  bonus_asset_ids: input.delivery?.bonus_asset_ids || [],

  // Drip content (for courses)
  drip_enabled: input.delivery?.drip_enabled || false,
  drip_schedule: input.delivery?.drip_schedule || null
};

// Marketing/SEO configuration
const marketing = {
  // Override auto-generated copy
  custom_title: input.marketing?.custom_title || null,
  custom_description: input.marketing?.custom_description || null,
  custom_short_description: input.marketing?.custom_short_description || null,

  // SEO
  seo_keywords: input.marketing?.seo_keywords || [],

  // Social proof
  testimonials: input.marketing?.testimonials || [],

  // Upsells
  upsell_product_ids: input.marketing?.upsell_product_ids || [],
  cross_sell_product_ids: input.marketing?.cross_sell_product_ids || []
};

// Affiliate program settings
const affiliates = {
  enabled: input.affiliates?.enabled || false,
  commission_percent: input.affiliates?.commission_percent || 30,
  cookie_days: input.affiliates?.cookie_days || 30
};

// Email/automation triggers
const automations = {
  // Post-purchase email sequence
  email_sequence_id: input.automations?.email_sequence_id || null,

  // Webhook on purchase
  purchase_webhook_url: input.automations?.purchase_webhook_url || null,

  // Add to email list
  add_to_list: input.automations?.add_to_list || null
};

return [{
  json: {
    asset_id: assetId,
    teaser_package_id: teaserPackageId,
    platforms: selectedPlatforms,
    pricing: pricing,
    product: product,
    delivery: delivery,
    marketing: marketing,
    affiliates: affiliates,
    automations: automations,
    callback_workflow: input.callback_workflow || null,
    session_id: `upload_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
    started_at: new Date().toISOString()
  }
}];

// Build platform-specific product listings
const config = $('Validate & Configure').first().json;
const asset = $('Fetch Asset').first().json;

let teaserPackage = null;
try {
  teaserPackage = $('Fetch Teaser Package').first()?.json || null;
} catch(e) {}

// Parse asset data
const title = asset.Title || 'Untitled Product';
let fileUrls = [];
try { fileUrls = JSON.parse(asset['File URLs'] || '[]'); } catch(e) {}

const totalWords = asset['Total Words'] || 0;
const estimatedPages = asset['Estimated Pages'] || Math.ceil(totalWords / 250);

// Parse teaser package for marketing copy
let landingPage = {};
let emailSubjects = [];
if (teaserPackage) {
  try { landingPage = JSON.parse(teaserPackage['Landing Page'] || '{}'); } catch(e) {}
  try { emailSubjects = JSON.parse(teaserPackage['Email Subjects'] || '[]'); } catch(e) {}
}

// Helper: Build product description
const buildDescription = (platform, maxLength = null) => {
  // Use custom or auto-generate from landing page
  let description = config.marketing.custom_description;

  if (!description && landingPage.hero) {
    description = `${landingPage.hero.headlines?.[0] || title}\n\n`;
    description += `${landingPage.hero.subheadline || ''}\n\n`;

    if (landingPage.problem?.pain_statements) {
      description += `Are you struggling with:\n`;
      landingPage.problem.pain_statements.slice(0, 3).forEach(p => {
        description += `• ${p}\n`;
      });
      description += '\n';
    }

    if (landingPage.solution?.transformation) {
      description += `${landingPage.solution.transformation}\n\n`;
    }

    if (landingPage.solution?.chapter_previews) {
      description += `What you'll learn:\n`;
      landingPage.solution.chapter_previews.slice(0, 5).forEach(ch => {
        description += `✓ ${ch.title}\n`;
      });
    }
  }

  if (!description) {
    description = `${title} - A comprehensive guide with ${estimatedPages} pages of actionable content.`;
  }

  // Platform-specific adjustments
  if (platform === 'etsy' && maxLength) {
    description = description.substring(0, maxLength);
  }

  return description;
};

// Helper: Build short description
const buildShortDescription = () => {
  if (config.marketing.custom_short_description) {
    return config.marketing.custom_short_description;
  }
  if (landingPage.hero?.subheadline) {
    return landingPage.hero.subheadline;
  }
  return `${estimatedPages}-page guide to mastering ${config.product.category.toLowerCase()}`;
};

// Helper: Get price for platform
const getPlatformPrice = (platform) => {
  const basePrice = config.pricing.base_price;
  const adjustment = config.pricing.platform_adjustments[platform] || 0;
  return Math.round((basePrice + adjustment) * 100) / 100;
};

// Helper: Get files for delivery
const getDeliveryFiles = () => {
  return fileUrls.filter(f => 
    config.delivery.include_formats.includes(f.format)
  );
};

// Build listing for each platform
const listings = config.platforms.map(platform => {
  const listing = {
    platform: platform,
    status: 'pending',

    // Basic info
    title: config.marketing.custom_title || title,
    short_description: buildShortDescription(),
    description: buildDescription(platform),

    // Pricing
    price: getPlatformPrice(platform),
    currency: config.pricing.currency,

    // Files
    files: getDeliveryFiles(),

    // Categorization
    category: config.product.category,
    subcategory: config.product.subcategory,
    tags: config.product.tags,

    // Settings
    visibility: config.product.visibility,
    publish_mode: config.product.publish_mode
  };

  // Platform-specific fields
  switch(platform) {
    case 'gumroad':
      listing.gumroad_specific = {
        pwyw: config.pricing.pwyw_enabled,
        minimum_price: config.pricing.pwyw_minimum,
        suggested_price: config.pricing.pwyw_suggested || config.pricing.base_price,
        is_physical: false,
        require_shipping: false,
        generate_license: false,
        max_purchase_count: null,
        affiliate_commission: config.affiliates.enabled ? config.affiliates.commission_percent : null
      };
      break;

    case 'etsy':
      listing.etsy_specific = {
        is_digital: true,
        who_made: 'i_did',
        when_made: 'made_to_order',
        taxonomy_id: null, // Will be set based on category
        shipping_profile_id: null, // N/A for digital
        processing_min: 1,
        processing_max: 1,
        // Etsy requires 5-13 tags
        tags: (config.product.tags || []).slice(0, 13),
        materials: ['Digital Download', 'PDF', 'Ebook'],
        // Etsy SEO
        title: (config.marketing.custom_title || title).substring(0, 140)
      };
      break;

    case 'amazon_kdp':
      listing.kdp_specific = {
        language: 'en',
        is_public_domain: false,
        has_adult_content: config.product.is_adult,
        // KDP categories (BISAC codes)
        bisac_primary: 'BUS000000', // General Business
        bisac_secondary: null,
        // Search keywords (up to 7)
        keywords: (config.marketing.seo_keywords || config.product.tags || []).slice(0, 7),
        // DRM
        drm_enabled: true,
        // Pricing
        royalty_plan: config.pricing.base_price >= 2.99 ? '70' : '35',
        // Territories
        territories: 'worldwide',
        // Series info
        series_title: null,
        series_number: null
      };
      break;

    case 'shopify':
      listing.shopify_specific = {
        product_type: 'Digital Download',
        vendor: 'Self',
        requires_shipping: false,
        taxable: true,
        inventory_management: null,
        inventory_policy: 'continue',
        fulfillment_service: 'manual',
        // Metafields for digital delivery
        metafields: {
          digital_download: true,
          file_count: getDeliveryFiles().length
        },
        // Variants (if tiers)
        variants: config.pricing.tiers || [{
          title: 'Default',
          price: getPlatformPrice('shopify'),
          sku: `${title.replace(/\s+/g, '-').toLowerCase()}-digital`
        }]
      };
      break;

    case 'payhip':
      listing.payhip_specific = {
        product_type: 'digital',
        file_types: config.delivery.include_formats,
        affiliate_enabled: config.affiliates.enabled,
        affiliate_commission: config.affiliates.commission_percent,
        limit_downloads: false,
        pdf_stamping: true,
        pay_what_you_want: config.pricing.pwyw_enabled
      };
      break;

    case 'lemonsqueezy':
      listing.lemonsqueezy_specific = {
        product_type: 'digital_download',
        status: config.product.publish_mode === 'immediate' ? 'published' : 'draft',
        // License
        license_enabled: false,
        // Variants
        has_variants: config.pricing.tiers ? true : false,
        // Checkout
        buy_now_url: true,
        // Integrations
        email_provider_integration: config.automations.add_to_list ? true : false
      };
      break;

    case 'kofi':
      listing.kofi_specific = {
        shop_item: true,
        is_nsfw: config.product.is_adult,
        // Ko-fi specific
        gold_exclusive: false,
        // Digital delivery
        digital_files: getDeliveryFiles().map(f => f.url)
      };
      break;

    case 'teachable':
    case 'thinkific':
      listing.course_specific = {
        course_type: 'self_paced',
        drip_enabled: config.delivery.drip_enabled,
        drip_schedule: config.delivery.drip_schedule,
        // Curriculum from chapters
        sections: [], // Would be built from content
        // Certificates
        certificate_enabled: true,
        // Pricing
        payment_type: 'one_time', // or 'subscription', 'payment_plan'
        enrollment_cap: null
      };
      break;
  }

  return listing;
});

return [{
  json: {
    ...config,
    asset: {
      id: asset.id,
      title: title,
      total_words: totalWords,
      estimated_pages: estimatedPages,
      file_urls: fileUrls
    },
    listings: listings
  }
}];

// Split listings for parallel platform uploads
const data = $input.first().json;
const listings = data.listings || [];

return listings.map(listing => ({
  json: {
    ...listing,
    asset: data.asset,
    pricing: data.pricing,
    automations: data.automations,
    session_id: data.session_id
  }
}));

// Process Gumroad response
const inputData = $('Split Platforms').item.json;
const response = $input.item.json;

let result = {
  platform: 'gumroad',
  status: 'failed',
  product_id: null,
  product_url: null,
  edit_url: null,
  error: null
};

if (response.success && response.product) {
  result = {
    platform: 'gumroad',
    status: 'success',
    product_id: response.product.id,
    product_url: response.product.short_url,
    edit_url: `https://app.gumroad.com/products/${response.product.id}/edit`,
    price: response.product.price / 100,
    currency: response.product.currency,
    published: response.product.published,
    error: null
  };
} else {
  result.error = response.message || 'Unknown error';
}

return [{ json: { ...inputData, result: result } }];

// Process Etsy response
const inputData = $('Split Platforms').item.json;
const response = $input.item.json;

let result = {
  platform: 'etsy',
  status: 'failed',
  listing_id: null,
  product_url: null,
  edit_url: null,
  error: null
};

if (response.listing_id) {
  result = {
    platform: 'etsy',
    status: 'success',
    listing_id: response.listing_id,
    product_url: response.url,
    edit_url: `https://www.etsy.com/your/shops/me/listings/${response.listing_id}`,
    price: response.price?.amount / response.price?.divisor || inputData.price,
    published: response.state === 'active',
    error: null
  };
} else {
  result.error = response.error || 'Unknown error';
}

return [{ json: { ...inputData, result: result } }];

// Handle other platforms (stubbed for now)
// In production, add specific API calls for each platform

const inputData = $input.item.json;
const platform = inputData.platform;

let result = {
  platform: platform,
  status: 'pending_manual',
  product_id: null,
  product_url: null,
  error: null,
  message: ''
};

switch(platform) {
  case 'amazon_kdp':
    result.message = 'Amazon KDP requires manual upload via kdp.amazon.com. Listing data prepared.';
    result.prepared_data = {
      title: inputData.title,
      description: inputData.description,
      keywords: inputData.kdp_specific?.keywords,
      bisac: inputData.kdp_specific?.bisac_primary,
      price: inputData.price
    };
    break;

  case 'shopify':
    result.message = 'Shopify integration ready. Configure store connection.';
    result.api_endpoint = '/admin/api/2024-01/products.json';
    break;

  case 'payhip':
    result.message = 'Payhip API integration available.';
    result.api_endpoint = 'https://payhip.com/api/v1/products';
    break;

  case 'lemonsqueezy':
    result.message = 'LemonSqueezy API integration available.';
    result.api_endpoint = 'https://api.lemonsqueezy.com/v1/products';
    break;

  case 'kofi':
    result.message = 'Ko-fi shop integration. Manual upload recommended.';
    break;

  case 'teachable':
  case 'thinkific':
    result.message = `${platform} course platform. API integration available for course creation.`;
    break;

  default:
    result.message = `Platform ${platform} not yet implemented.`;
}

return [{ json: { ...inputData, result: result } }];

// Build comprehensive results summary
const config = $('Build Platform Listings').first().json;
const allResults = $input.first().json.data || [];

const completedAt = new Date().toISOString();
const durationMs = new Date(completedAt) - new Date(config.started_at);

// Categorize results
const successful = allResults.filter(r => r.result?.status === 'success');
const pending = allResults.filter(r => r.result?.status === 'pending_manual');
const failed = allResults.filter(r => r.result?.status === 'failed');

// Build product links
const productLinks = successful.map(r => ({
  platform: r.result.platform,
  url: r.result.product_url,
  edit_url: r.result.edit_url,
  price: r.result.price,
  published: r.result.published
}));

// Build revenue projections
const avgPrice = successful.reduce((sum, r) => sum + (r.result.price || 0), 0) / (successful.length || 1);
const projections = {
  price_avg: Math.round(avgPrice * 100) / 100,
  at_10_sales: Math.round(avgPrice * 10 * 100) / 100,
  at_50_sales: Math.round(avgPrice * 50 * 100) / 100,
  at_100_sales: Math.round(avgPrice * 100 * 100) / 100
};

return [{
  json: {
    success: true,
    session_id: config.session_id,

    // Product info
    product: {
      title: config.asset.title,
      pages: config.asset.estimated_pages,
      words: config.asset.total_words
    },

    // Upload summary
    summary: {
      platforms_requested: config.platforms.length,
      successful: successful.length,
      pending_manual: pending.length,
      failed: failed.length
    },

    // Product links (the important stuff!)
    product_links: productLinks,

    // Pending manual uploads
    pending_actions: pending.map(r => ({
      platform: r.result.platform,
      message: r.result.message,
      prepared_data: r.result.prepared_data
    })),

    // Failed uploads
    errors: failed.map(r => ({
      platform: r.result.platform,
      error: r.result.error
    })),

    // Revenue projections
    revenue_projections: projections,

    // Timing
    duration_seconds: Math.round(durationMs / 1000),

    // Next steps
    next_steps: [
      successful.length > 0 ? 'Products are live! Share your links.' : null,
      pending.length > 0 ? `Complete manual uploads for: ${pending.map(p => p.result.platform).join(', ')}` : null,
      failed.length > 0 ? `Retry failed platforms: ${failed.map(f => f.result.platform).join(', ')}` : null,
      'Set up email automation for buyers',
      'Create social media launch posts',
      'Configure affiliate program'
    ].filter(Boolean),

    // Metadata
    asset_id: config.asset_id,
    callback_workflow: config.callback_workflow
  }
}];

