={
  "product_id": "{{ $('Save Product Record').first().json.id }}",
  "title": "{{ $('Build Response').first().json.product.title }}",
  "product_links": {{ JSON.stringify($('Build Response').first().json.product_links) }},
  "summary": {{ JSON.stringify($('Build Response').first().json.summary) }}
}
